{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configuration, which could allow unintended public access to sensitive data."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, which makes it difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket does not explicitly block public ACLs, which could allow public access if ACLs are misconfigured."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket = \"fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}\"\n\n  # Block public access\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n\n  # Enable access logging\n  logging {\n    target_bucket = \"logging-bucket-name\" # Replace with the name of a dedicated logging bucket\n    target_prefix = \"cloudtrail-logs/\"\n  }\n}",
  "fix_summary": "Added a Public Access block to prevent unintended public access and explicitly block public ACLs. Enabled access logging to track access patterns and detect unauthorized access."
}
